A logging decorator wraps a caching decorator that wraps the real repository. Put the printed lines in order, first to last.

```csharp
IRepo repo = new Logging(new Caching(new Db()));
repo.Get(7);
repo.Get(7);

interface IRepo { string Get(int id); }
class Db : IRepo { public string Get(int id) { Console.WriteLine("db query"); return "row"; } }
class Caching(IRepo inner) : IRepo {
    readonly Dictionary<int, string> cache = new();
    public string Get(int id) {
        if (cache.TryGetValue(id, out var v)) { Console.WriteLine("cache hit"); return v; }
        Console.WriteLine("cache miss");
        return cache[id] = inner.Get(id);
    }
}
class Logging(IRepo inner) : IRepo {
    int calls;
    public string Get(int id) { Console.WriteLine($"log call {++calls}"); return inner.Get(id); }
}
```

A chain of approvers each handle a request or pass it on. Put the printed lines in order, first to last.

```go
package main

import "fmt"

type Handler interface{ Handle(amount int) }

type Approver struct {
	name  string
	limit int
	next  Handler
}

func (a *Approver) Handle(amount int) {
	if amount <= a.limit {
		fmt.Println(a.name, "approves", amount)
		return
	}
	fmt.Println(a.name, "passes", amount)
	if a.next != nil {
		a.next.Handle(amount)
	}
}

func main() {
	ceo := &Approver{name: "ceo", limit: 100000}
	director := &Approver{name: "director", limit: 10000, next: ceo}
	manager := &Approver{name: "manager", limit: 1000, next: director}
	lead := &Approver{name: "lead", limit: 100, next: manager}
	lead.Handle(50000)
	manager.Handle(50)
}
```

