Observers are notified in the order they subscribed. Put the printed lines in order, first to last.

```js
class Subject {
  #observers = [];
  subscribe(fn) { this.#observers.push(fn); return () => { this.#observers = this.#observers.filter(o => o !== fn); }; }
  notify(msg) { for (const o of this.#observers) o(msg); }
}
const s = new Subject();
s.subscribe(m => console.log("email " + m));
const stopSms = s.subscribe(m => console.log("sms " + m));
s.notify("A");
stopSms();
s.subscribe(m => console.log("push " + m));
s.notify("B");
```

