This is a Koa-style middleware pipeline where each middleware awaits `next()`. Put the printed lines in order, first to last.

```js
const stack = [];
const use = (mw) => stack.push(mw);
function run(ctx) {
  const dispatch = async (i) => { const mw = stack[i]; if (mw) await mw(ctx, () => dispatch(i + 1)); };
  return dispatch(0);
}
use(async (ctx, next) => { console.log("timer start"); await next(); console.log("timer end"); });
use(async (ctx, next) => { console.log("auth check"); await next(); console.log("auth done"); });
use(async (ctx) => { console.log("handler"); });
run({});
```

`Chain` wraps a handler with middleware in the order given. Put the printed lines in order, first to last.

```go
package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
)

type Middleware func(http.Handler) http.Handler

func named(name string) Middleware {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			fmt.Println(name, "before")
			next.ServeHTTP(w, r)
			fmt.Println(name, "after")
		})
	}
}

func Chain(h http.Handler, mws ...Middleware) http.Handler {
	for _, mw := range mws {
		h = mw(h)
	}
	return h
}

func main() {
	app := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { fmt.Println("handler") })
	h := Chain(app, named("logging"), named("auth"))
	h.ServeHTTP(httptest.NewRecorder(), httptest.NewRequest("GET", "/", nil))
}
```

