A visitor computes the total area of some shapes. Put the printed lines in order, first to last.

```go
package main

import "fmt"

type Visitor interface {
	VisitCircle(c Circle)
	VisitSquare(s Square)
}

type Shape interface{ Accept(v Visitor) }

type Circle struct{ R float64 }
type Square struct{ Side float64 }

func (c Circle) Accept(v Visitor) { fmt.Println("circle accept"); v.VisitCircle(c) }
func (s Square) Accept(v Visitor) { fmt.Println("square accept"); v.VisitSquare(s) }

type AreaVisitor struct{ total float64 }

func (a *AreaVisitor) VisitCircle(c Circle) { fmt.Println("visit circle"); a.total += 3 * c.R * c.R }
func (a *AreaVisitor) VisitSquare(s Square) { fmt.Println("visit square"); a.total += s.Side * s.Side }

func main() {
	shapes := []Shape{Square{2}, Circle{1}}
	v := &AreaVisitor{}
	for _, s := range shapes {
		s.Accept(v)
	}
	fmt.Println("total", v.total)
}
```

