This Go 1.23+ iterator is consumed with `range` and the loop breaks early. Put the printed lines in order, first to last.

```go
package main

import (
	"fmt"
	"iter"
)

func Countdown(from int) iter.Seq[int] {
	return func(yield func(int) bool) {
		defer fmt.Println("cleanup")
		for i := from; i > 0; i-- {
			fmt.Println("produce", i)
			if !yield(i) {
				fmt.Println("stopped")
				return
			}
		}
	}
}

func main() {
	for n := range Countdown(5) {
		if n == 4 {
			break
		}
		fmt.Println("consume", n)
	}
}
```

