A macro command runs its steps in order. In what order are the `undo` lines printed, first to last?

```csharp
var macro = new Macro(new Step("format"), new Step("lint"), new Step("test"), new Step("save"));
macro.Execute();
macro.Undo();

interface ICommand { void Execute(); void Undo(); }
class Step(string name) : ICommand {
    public void Execute() { }
    public void Undo() => Console.WriteLine($"undo {name}");
}
class Macro(params ICommand[] steps) : ICommand {
    public void Execute() { foreach (var s in steps) s.Execute(); }
    public void Undo() { foreach (var s in steps.Reverse()) s.Undo(); }
}
```

