A Unit of Work records changes in any order and writes them on `Commit`. Put the printed lines in order, first to last.

```go
package main

import "fmt"

type UnitOfWork struct{ news, dirty, removed []string }

func (u *UnitOfWork) RegisterNew(e string)     { u.news = append(u.news, e) }
func (u *UnitOfWork) RegisterDirty(e string)   { u.dirty = append(u.dirty, e) }
func (u *UnitOfWork) RegisterRemoved(e string) { u.removed = append(u.removed, e) }

func (u *UnitOfWork) Commit() {
	for _, e := range u.news {
		fmt.Println("INSERT", e)
	}
	for _, e := range u.dirty {
		fmt.Println("UPDATE", e)
	}
	for _, e := range u.removed {
		fmt.Println("DELETE", e)
	}
}

func main() {
	u := &UnitOfWork{}
	u.RegisterRemoved("coupon")
	u.RegisterDirty("customer")
	u.RegisterNew("order")
	u.RegisterDirty("stock")
	u.RegisterNew("invoice")
	u.Commit()
}
```

A constructor uses Go's functional options pattern. Put the printed lines in order, first to last.

```go
package main

import "fmt"

type Server struct {
	port int
	tls  bool
}

type Option func(*Server)

func WithPort(p int) Option { return func(s *Server) { fmt.Println("port", p); s.port = p } }
func WithTLS() Option       { return func(s *Server) { fmt.Println("tls on"); s.tls = true } }

func NewServer(opts ...Option) *Server {
	s := &Server{port: 80}
	fmt.Println("defaults", s.port)
	for _, opt := range opts {
		opt(s)
	}
	fmt.Println("ready", s.port, s.tls)
	return s
}

func main() {
	NewServer(WithTLS(), WithPort(8443))
}
```
